<?php $title='Profile | ScholarHub';require 'includes/header.php';require 'config/db.php';if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}$id=$_SESSION['user_id'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$st=$pdo->prepare('UPDATE users SET name=?,target_country=?,study_level=?,field=? WHERE id=?');$st->execute([trim($_POST['name']),trim($_POST['target_country']),trim($_POST['study_level']),trim($_POST['field']),$id]);$msg='Profile updated.';}$st=$pdo->prepare('SELECT * FROM users WHERE id=?');$st->execute([$id]);$u=$st->fetch(); ?><div class="container py-5"><div class="row justify-content-center"><div class="col-lg-8"><div class="card p-4"><h2>My Profile</h2><?php if($msg): ?><div class="alert alert-success"><?=e($msg)?></div><?php endif; ?><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input class="form-control" name="name" value="<?=e($u['name'])?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" value="<?=e($u['email'])?>" disabled></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" value="" placeholder="Phone number"></div><div class="col-md-6"><label class="form-label">Target country</label><input class="form-control" name="target_country" value="<?=e($u['target_country'])?>"></div><div class="col-md-6"><label class="form-label">Study level</label><input class="form-control" name="study_level" value="<?=e($u['study_level'])?>"></div><div class="col-md-6"><label class="form-label">Field</label><input class="form-control" name="field" value="<?=e($u['field'])?>"></div></div><button class="btn btn-primary mt-4">Save</button></form></div></div></div></div><?php require 'includes/footer.php'; ?>
